  "about.founderHeading": "📖 عن المؤسِّسة",
  "about.founder.p1": "مرحبًا، أنا كونسبسيون، مؤسِّسة Luminous StockHaven.",
  "about.founder.p2": "أنا لا أنتمي إلى شركة تقنية كبيرة، ولا أجلس في مكتب شركة. أنا صاحبة متجر تجزئة صغير، مثلك تمامًا. أدير خمسة متاجر إلكترونية متخصصة في الكتب والإكسسوارات اليدوية لمحبي الكتب.\nومثل كثير من تجار التجزئة المستقلين، وصلت إلى نقطة الانهيار وأنا أحاول إدارة المخزون في مواقع متعددة، وتتبّع أرقام ISBN الخاصة بالناشرين إلى جانب رموز SKU اليدوية الخاصة بي، والتعامل مع طلبات الموردين باستخدام جداول بيانات معقّدة. وعندما بحثت عن تطبيق يساعدني، جرّبت ستة خيارات مختلفة. كان كل واحد منها إما ناقصًا تمامًا، أو مربكًا بشكل لا يُصدق، أو جشعًا — يفرض مئات الدولارات شهريًا مقابل أدوات أساسية.",
  "about.founder.p3": "وبسبب إحباطي من صناعة تستغل المبدعين المستقلين، قررت بناء الحل الخاص بي. بنيت Luminous StockHaven بدافع الضرورة، لأدير أعمالي بنفسي بشكل نظيف وفعّال وبطمأنينة تامة.",
  "about.founder.p4": "قررت فتح هذه المنصة للجمهور بسعر صادق ومعقول، لأن كل صاحب متجر صغير يستحق أدوات تعمل فعلًا دون المخاطرة بدخله. نحن مملوكون بشكل مستقل، ونحمي مجتمعنا بشراسة، وبنينا بواسطة تاجرة تجزئة، من أجل تجار التجزئة.",
  "notice.ariaLabel": "إشعار العلامات التجارية وحقوق النشر",
