  "settings.details.taxModeHint": "يستخدم الوضع الثابت معدلك في كل طلب جديد. ويملأ الوضع التلقائي ضريبة الطلب الجديد بمعدل الولاية الأساسي للعميل بمجرد وجود الولاية في الطلب، ويعيد ملأها إذا تغيرت الولاية. هذه معدلات ولايات أساسية — قد تضيف الضرائب المحلية المزيد. الطلب الذي بلا ولاية، أو من خارج الولايات المتحدة، يستخدم معدلك الثابت أعلاه.",
  'settings.details.gs1Prefix': "بادئة شركة GS1",
