  "auth.sameEmailNotice": "لديك تطبيقنا بالفعل من Google Play أو App Store؟ استخدم البريد الإلكتروني نفسه هنا — الذي تسجّل الدخول به إلى التطبيق — حتى يأتي متجرك ومخزونك معك. بريد إلكتروني مختلف يبدأ واجهة متجر جديدة تمامًا وفارغة.",
