  "crossStore.transferTarget": "انقل إلى",
  "crossStore.transferTitle": "نقل المخزون إلى متجر آخر",
  "crossStore.transferToFirstLocation": "موقعه الأول",
  "crossStore.transferToLocation": "إلى الموقع",
  "training.lessons.owner-move-stock.step1": "الطلبات للسؤال؛ أما النقل فهو شأن المالك. في صفحة صندوق الوارد بين المتاجر، تتيح لك لوحة نقل المخزون — أنت المالك — إرسال المخزون مباشرة من هذا المتجر إلى متجر آخر تملكه، دون طلب ودون انتظار.",
  "training.lessons.owner-move-stock.step2": "اختر المنتج والموقع الذي يغادر منه والكمية. يعرض التطبيق كم هو متوفر في ذلك الموقع، ولا يمكن لأي نقل أن يأخذ أكثر من ذلك أبدًا.",
  "training.lessons.owner-move-stock.step3": "اختر المتجر الوجهة، والموقع الدقيق فيه إن أردت. إذا كان لدى ذلك المتجر نفس SKU بالفعل، ينضم المخزون إلى ذلك المنتج؛ وإن لم يكن، يُنسخ المنتج مع المخزون.",
  "training.lessons.owner-move-stock.step4": "يحتفظ كلا المتجرين بسجل: يعرض هذا المتجر تحويلًا صادرًا، ويعرض الآخر استلامًا. وإذا تعذر النقل — لعدم كفاية المتوفر، أو لأن المتجر الآخر ليس لك — فلا يتحرك شيء ويخبرك التطبيق بالسبب.",
  "training.lessons.owner-move-stock.title": "نقل المخزون بين متاجرك (خطة Business)",
  "plansLib.feature.pricing": "أسعار التصفية والتخفيض المؤقت",
