  "pricing.modeRollback": "تخفيض مؤقت (بيع مؤقت)",
  "pricing.rollbackBadge": "تخفيض",
  "pricing.rollbackHint": "يُحفظ السعر المعتاد ويُعرض بجانب سعر التخفيض المؤقت أثناء البيع. وعندما ينقضي تاريخ الانتهاء، يعود السعر إلى المعتاد من تلقاء نفسه.",
  "pricing.rollbackStarts": "يبدأ التخفيض المؤقت في {date}",
  "pricing.salePriceLabel": "سعر التخفيض المؤقت",
  "pricing.sectionTitle": "أسعار البيع",
  "pricing.startLabel": "يبدأ",
  "training.lessons.mgr-pricing.step1": "في Business، يحتوي نموذج المنتج على قسم لأسعار البيع. التصفية تخفيض دائم — حدّدها وستبقى. التخفيض المؤقت بيع بتواريخ: حدّد سعر التخفيض، ويوم بدئه، ويوم انتهائه.",
  "training.lessons.mgr-pricing.step2": "لا تحتاج أبدًا إلى إعادة كتابة السعر المعتاد: يبقى على المنتج ويظهر بجانب سعر البيع في قائمة المنتجات وعلى الماسح، ليرى أي شخص كم يكلف الصنف عادة.",
  "training.lessons.mgr-pricing.step3": "اطبع ملصقات أسعار جديدة عندما يبدأ تخفيض مؤقت — تطبع الملصقات السعر الذي يدفعه العميل في ذلك اليوم. وعندما ينقضي تاريخ الانتهاء، يعود السعر إلى المعتاد من تلقاء نفسه؛ اطبع ملصقات معتادة مرة أخرى عندما تجدّد الرف.",
  "training.lessons.mgr-pricing.step4": "إذا ظهر قسم أسعار البيع مقفلًا، فإن النشاط التجاري ليس على خطة Business — أسعار البيع تخص تلك الخطة، والمالك هو من يغيّر الخطط.",
  "training.lessons.mgr-pricing.title": "إدارة بيع: التصفيات والتخفيضات المؤقتة",
  "training.lessons.owner-pricing.step1": "يعيش نوعان من التخفيض في نموذج المنتج، تحت أسعار البيع. التصفية دائمة: حدد سعر التصفية وسيبقى منخفضًا حتى تغيّره مرة أخرى. التخفيض المؤقت بيع مؤقت — سعر أقل بتاريخ بدء وتاريخ انتهاء، مثل التخفيضات التي تعرفها من المتاجر الكبيرة.",
  "training.lessons.owner-pricing.step2": "السعر المعتاد لا يُمحى أبدًا. أثناء التخفيض المؤقت، يعرض التطبيق سعر البيع مع السعر المعتاد بجانبه، وتحمل الملصقات المطبوعة سعر البيع، ليتطابق الرف مع الصندوق.",
  "training.lessons.owner-pricing.step3": "عندما ينقضي تاريخ الانتهاء، يعود السعر إلى المعتاد من تلقاء نفسه — لا شيء لتتذكره، ولا شيء لتتراجع عنه. التخفيض المؤقت الذي لم يبدأ بعد يخبرك بتاريخ بدئه، مباشرة في قائمة المنتجات.",
  "training.lessons.owner-pricing.step4": "أسعار البيع ميزة من خطة Business. في Essentials تبقى الحقول مقفلة، وإذا نزل نشاط تجاري إلى Essentials ثم عاد، فإن إعدادات التصفية والتخفيض المؤقت لديه ما تزال موجودة، تمامًا كما تُركت.",
  "training.lessons.owner-pricing.title": "أسعار التصفية والتخفيض المؤقت (خطة Business)",
