  "print.shippingNote": "إذا كان الطلب يحمل عنوان شحن، فإنه يُملأ من الطلب. ما تكتبه هنا يُطبع مرة واحدة ولا يُحفظ أبدًا.",
  "print.carrier.title": "ملصق شركة الشحن الخاص بك",
  "print.carrier.desc": "اشترِ الطابع من شركة الشحن، كما تفعل اليوم — هذا التطبيق لا يبيع الطوابع أبدًا، لذا فإن السعر الذي تدفعه هو دائمًا سعر شركة الشحن نفسها. احفظ ملف الملصق هنا وسيبقى على هذا الطلب للأبد: سجلّك، في متناول يدك إن حدث أي شيء.",
