  "print.style.title": "أسلوب المستندات",
  "print.style.desc": "اجعل مستنداتك ملكك. تُلبس هذه الخيارات فاتورتك وإيصالك وقائمة التعبئة ومستندات الإرجاع وأوراق المنتجات وأوراق الجرد وقوائم الالتقاط — وتُحفظ لنشاطك التجاري.",
