  "print.style.saveFailed": "تعذّر حفظ الأسلوب. لم يتغيّر شيء — حاول مرة أخرى.",
  "print.style.previewText": "الثعلب البني السريع يقفز فوق الكلب الكسول. 1234567890",
  "training.lessons.owner-shipping-labels.step1": "يضم مركز الطباعة نمط ملصق شحن في كلتا الخطتين: اختر طلب عميل واطبع ملصق 4×6 باسم المشتري وعنوانه ونشاطك التجاري بصفتك المرسِل.",
  "training.lessons.owner-shipping-labels.step2": "الملصق بلا علامة تجارية، مثل كل مستند للعميل: يحمل اسم نشاطك التجاري فقط — ولا يحمل أبدًا اسم هذا التطبيق — لكي يبدو الطرد القادم من متجرك وكأنه جاء من متجرك.",
  "training.lessons.owner-shipping-labels.step3": "يتم الاحتفاظ بعنوان العميل مع طلباته لمدة 90 يومًا بعد طلبه الأخير، وتبدأ الملصقة من العنوان المخزن للطلب عندما يكون له واحد؛ العنوان الذي يتم كتابته في وقت الطباعة لملصقة لمرة واحدة لا يتم حفظه مرة أخرى. لا يزال الاسم يملأ من الطلب حتى تتطابق الملصقة مع الأوراق.",
  "training.lessons.owner-shipping-labels.step4": "يُطبع الملصق عبر الاتصالات الأربعة نفسها التي تستخدمها كل الملصقات — البلوتوث والواي فاي والإيثرنت وUSB — والطابعة الحرارية 4×6 هي مقاسه القياسي.",
  "training.lessons.owner-shipping-labels.step5": "اشتريت الطابع من شركة الشحن بدلًا من ذلك؟ في هذا القسم نفسه يمكنك رفع ملف ملصق شركة الشحن — PDF أو PNG أو JPG — وسيبقى محفوظًا على الطلب للأبد: سجلّك، في متناول يدك إن حدث أي شيء. يُطبع بحجمه الحقيقي 4×6. التطبيق لا يبيع الطوابع أبدًا، لذا فإن سعر شركة الشحن هو السعر الوحيد — وهو دائمًا السعر الصحيح.",
  "training.lessons.owner-shipping-labels.title": "ملصقات الشحن لطلبات العملاء",
  "training.lessons.print-shipping-label.step1": "عندما يكون الطلب جاهزًا للإرسال، افتح مركز الطباعة واختر نمط ملصق الشحن ثم اختر طلب العميل. يُملأ اسم المشتري من الطلب.",
  "training.lessons.print-shipping-label.step2": "تحقق من العنوان الذي سيذهب إليه الطرد. عندما يحمل الطلب عنوان العميل — المحفوظ لمدة 90 يومًا بعد طلبه الأخير — فإنه يملأ لك؛ العنوان الذي تكتبه في وقت الطباعة لا يتم حفظه مرة أخرى، لذا تحقق من الرمز البريدي والسطر الأخير بعناية قبل الطباعة.",
  "training.lessons.print-shipping-label.step3": "يُطبع اسم نشاطك التجاري في الأعلى بصفتك المرسِل. إذا أردت أن يظهر عنوانك أيضًا على الملصق، فاكتبه في خانة عنوان المرسِل؛ واتركه فارغًا إذا كنت تفضل ألا يظهر.",
  "training.lessons.print-shipping-label.step4": "اطبع على ملصق 4×6 — طابعة الملصقات الحرارية هي الخيار المعتاد — أو على أي طابعة عبر زر طباعة المتصفح. ألصق الملصق مستويًا على الطرد، حيث لا ينثني على حافة.",
  "training.lessons.print-shipping-label.step5": "إذا اشتُري الطابع من شركة الشحن، احفظ ملف ملصقها على الطلب بدلًا من ذلك: ارفع ملف PDF أو PNG أو JPG الذي أعطتك إياه شركة الشحن في قسم ملصق شركة الشحن الخاص بك. يبقى على الطلب كسجلّك ويُطبع بحجمه الحقيقي 4×6 — وملصق عنوان التطبيق موجود دائمًا عندما تفضّل استخدامه.",
  "training.lessons.print-shipping-label.title": "اطبع ملصق شحن",
