  "staff.memberDialog.settingsAccessHint": "تظهر الأقسام المُعلَّمة في إعدادات هذا الشخص، حيث يمكنه رؤيتها وتغييرها. وتبقى الأقسام غير المُعلَّمة مخفية. لا يوجد اشتراك ولا فوترة هنا أبدًا — فهما للمالك وحده.",
