  "apiErrors.graceReadOnly": "مساحة العمل هذه للقراءة فقط: انتهى الاشتراك، وفترة السماح البالغة 15 يومًا تسمح بعرض المنتجات فقط. لا تغييرات ولا مسح ولا استيراد ولا تصدير.",
  "apiErrors.subscriptionRequired": "مساحة العمل هذه ليس لديها اشتراك نشط. اشترك في خطة لاستخدامها — يبدأ الوصول فقط عند تأكيد الفترة التجريبية أو الدفع.",
