  "staff.memberDialog.returnsAccessHint": "بهذه العلامة، يمكن لهذا الشخص الموافقة على مرتجع وإكمال الاسترداد أو الاستبدال. وبدونها، ينتظر المرتجع الذي يبدأه المالك أو عضو فريق معتمد.",
