  "staff.memberDialog.productsAccessHint": "بهذه العلامة، يرى هذا الشخص أزرار «منتج جديد» ويمكنه إضافة منتجات إلى الكتالوج. وبدونها، لا تظهر له الأزرار.",
  "productForm.readIsbnTitle": "قراءة رقم ISBN المطبوع",
  "productForm.readIsbnHint": "وجّه الكاميرا إلى رقم ISBN المطبوع على الكتاب، ثم اضغط «قراءة الرقم». وإذا أمكن قراءة الباركود، فإنه يملأ الرقم أيضًا.",
  "productForm.readIsbnButton": "قراءة الرقم",
