  "staffLib.area.locationsAccess": "إضافة المواقع",
  "staff.memberDialog.locationsAccessHint": "بهذه العلامة، يمكن لهذا الشخص إضافة مواقع جديدة. وبدونها، يمكن للمالك فقط إضافة موقع، ولا تظهر له أزرار الإضافة.",
  "apiErrors.locationsCreateReserved": "فقط المالك، أو عضو فريق سمح له المالك بإضافة مواقع، يمكنه إضافة موقع.",
  "settings.policies.title": "سياسات متجرك وشروطه",
  "settings.policies.ownerDescription": "متجرك وقواعدك. اكتب هنا سياسات متجرك وشروطك وأحكامك — اكتبها بنفسك أو ارفع ملفًا. كل عضو جديد في الفريق يراها مرة واحدة عندما يبدأ، ويمكن لفريقك كله قراءتها هنا في أي وقت. أنت وحدك من يستطيع تغييرها.",
  "settings.policies.memberDescription": "سياسات متجرك وشروطه الخاصة، كتبها المالك. المالك وحده يستطيع تغييرها.",
