  "training.lessons.your-profile-photo.title": "صورة ملفك الشخصي",
  "training.lessons.your-profile-photo.step1": "تظهر صورتك بجانب اسمك في أعلى التطبيق، وفي صفحة الموظفين، وبجانب رسائلك — بمجرد أن يوافق عليها المالك. وحتى ذلك الحين، تظهر الأحرف الأولى من اسمك فقط.",
  "training.lessons.your-profile-photo.step2": "افتح الإعدادات وابحث عن صورة ملفك الشخصي. اختر صورة لك وأرسلها. تذهب إلى المالك للموافقة عليها — ولا تظهر في أي مكان أثناء انتظارها.",
  "training.lessons.your-profile-photo.step3": "عندما يوافق المالك عليها، يرن جرسك وتبدأ صورتك في الظهور. وإذا لم تتم الموافقة عليها، اختر صورة مختلفة وأرسلها بدلًا منها.",
  "training.lessons.your-profile-photo.step4": "تغيير صورتك يعمل بالطريقة نفسها: تنتظر الصورة الجديدة الموافقة، وتبقى صورتك الحالية في مكانها حتى تتم الموافقة على الجديدة. وإذا لم تتم الموافقة على التغيير، تحتفظ بصورتك الأخرى.",
  "training.lessons.owner-profile-photos.title": "صور الملفات الشخصية واسمك",
  "training.lessons.owner-profile-photos.step1": "تظهر صورة كل شخص بجانب اسمه في أعلى التطبيق، وفي صفحة الموظفين الخاصة بك، وبجانب رسائلهم. لا تظهر صورة أي عضو في الفريق في أي مكان حتى توافق عليها — الموافقة لك وحدك، ولا يمكن لأحد الموافقة على صورته الخاصة.",
  "training.lessons.owner-profile-photos.step2": "عندما يرسل شخص ما صورة، يرن جرسك. افتح صفحة الموظفين لرؤيتها، ثم اختر موافقة أو عدم الموافقة. وإذا لم توافق عليها، يُقال للشخص أن يختار صورة أخرى.",
  "training.lessons.owner-profile-photos.step3": "إذا غيّر شخص ما صورته، تنتظر الصورة الجديدة موافقتك بالطريقة نفسها. تبقى صورته الحالية في مكانها أثناء انتظارها — وتبقى إذا لم توافق على التغيير.",
  "training.lessons.owner-profile-photos.step4": "صورتك الخاصة لا تحتاج إلى موافقة: عيّنها في الإعدادات، ضمن صورة ملفك الشخصي. تحمل البطاقة نفسها اسمك أيضًا — الاسم الذي تعيّنه هناك يحل محل كلمة المالك في كل مكان يراه فريقك، في التطبيق وفي الرسائل.",
