  "training.lessons.mgr-clock-callin.title": "الاستدعاءات وتصحيحات الساعة",
  "training.lessons.mgr-clock-callin.step1": "يمكن للمالك أن يعطي المدير علامة واحدة — الاستدعاءات وتصحيحات الساعة. وبها، يمكنك فتح نافذة استدعاء لأحد الموظفين وتصحيح سجلات الوقت من صفحة الموظفين.",
  "training.lessons.mgr-clock-callin.step2": "تتيح نافذة الاستدعاء لشخص تسجيل الدخول والبدء عندما لا تغطيه أي وردية. افتحها من صفحة الموظفين، على بطاقة الاستدعاءات والمغادرات الفائتة.",
  "training.lessons.mgr-clock-callin.step3": "تبقى النافذة مفتوحة حتى يسجّل ذلك الشخص مغادرته — ثم تتبعها مهلة العشر دقائق المعتادة قبل تسجيل الخروج — أو حتى تغلقها أنت أو المالك مبكراً. لا شيء يغلقها من تلقاء نفسه.",
  "training.lessons.mgr-clock-callin.step4": "عندما ينسى شخص تسجيل مغادرته، يُعلَّم سجله في صفحة الموظفين وفي كشوف الرواتب بمجرد انتهاء الوردية المجدولة، ويتم إشعارك أنت والمالك. يستمر السجل في العدّ حتى يتم تصحيحه.",
  "training.lessons.mgr-clock-callin.step5": "صحّح السجل من صفحة الموظفين: حدّد الدخول والمغادرة وأوقات الاستراحات. يصحّح المدير سجلات الموظفين فقط — أما سجلات المدير فيصحّحها المالك.",
  "staffLib.perm.staffDocuments": "مستندات الموظفين",
  "staffLib.area.documentsAccess": "مستندات الموظفين",
  "staff.memberDialog.documentsAccessHint": "للمديرين فقط — بهذه العلامة، يستطيع هذا المدير فتح ملفات مستندات أعضاء الفريق: الأوراق المحفوظة لكل شخص، مثل نماذج W-4 وطلبات التوظيف ونسخ الهوية. سيُطلب منك التأكيد أولًا — تحتوي هذه الملفات على أرقام الضمان الاجتماعي وتواريخ الميلاد. هذه العلامة لا تفعل شيئًا للموظفين.",
