  "training.lessons.owner-staff-documents.title": "مستندات الموظفين",
  "training.lessons.owner-staff-documents.step1": "لكل شخص في فريقك ملف مستندات في صفحة الفريق. ارفع الأوراق التي تحتفظ بها له — نموذج W-4 وطلب التوظيف ونماذج الضرائب ونسخة من هويته — وامنحها عنوانًا، أو احتفظ باسم الملف.",
  "training.lessons.owner-staff-documents.step2": "كل رفع يُحفظ. إضافة نسخة أحدث لا تحذف السابقة أبدًا — تبقى كل النسخ في القائمة، الأحدث أولًا، ولكل منها تاريخها واسم من رفعها.",
  "training.lessons.owner-staff-documents.step3": "وحدك ترى مستندات الموظفين، ما لم تمنح مديرًا علامة مستندات الموظفين في سجل عضويته. العلامة متوقفة افتراضيًا، ولا يحملها أي دور.",
  "training.lessons.owner-staff-documents.step4": "قبل أن تُفعَّل العلامة، يقول تحذير ما تعنيه: سيتمكن هذا الشخص من رؤية معلومات سرية عن أعضاء فريقك، بما في ذلك أرقام الضمان الاجتماعي وتواريخ الميلاد. الشخص الذي يخصه المستند لا يرى ملفه أبدًا.",
  "training.lessons.mgr-staff-documents.title": "مستندات الموظفين",
  "training.lessons.mgr-staff-documents.step1": "لقد ائتمنك المالك على علامة مستندات الموظفين. في صفحة الفريق، يمكنك فتح ملف مستندات أعضاء الفريق في فريقك.",
  "training.lessons.mgr-staff-documents.step2": "كل ملف يحتفظ بكل نسخة: عندما تضيف نسخة أحدث، تبقى النسخ السابقة مدرجة تحتها، الأحدث أولًا، ولكل منها تاريخها واسم من رفعها.",
  "training.lessons.mgr-staff-documents.step3": "قد تحتوي هذه الملفات على أرقام ضمان اجتماعي وتواريخ ميلاد ومعلومات خاصة أخرى. افتح فقط ما تحتاجه، ولا تشارك مستندًا خارج العمل أبدًا.",
  "training.lessons.mgr-staff-documents.step4": "يمكن للمالك استعادة العلامة في أي وقت، ويُغلق الباب فورًا. مستندات المدير الخاصة تبقى لدى المالك وحده.",
